unsigned off_dst = (unsigned)(*FUZZ_PARAM(unsigned int) % n);
unsigned maxlen = n - (off_src > off_dst ? off_src : off_dst);
unsigned size = maxlen;
mem_move((void*)(buf.data()+off_dst), (const void*)(buf.data()+off_src), size);

