def _rand_bytes(r: random.Random, n: int) -> bytes:
    # Mix of printable and arbitrary bytes to cover text/binary cases
    out = bytearray()
    for _ in range(n):
        choice = r.random()
        if choice < 0.5:
            # ASCII letters/digits/punct incl. whitespace
            out.append(r.choice(list(b"\t\n\r ")+list(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.:,;[]{}()!@#$%^&*+=")))
        elif choice < 0.7:
            # Zero bytes and small control values
            out.append(r.randint(0, 3))
        else:
            out.append(r.getrandbits(8))
    return bytes(out)

def _random_ipv4(r: random.Random) -> str:
    # Sometimes special forms
    specials = [
        "0.0.0.0",
        "127.0.0.1",
        "255.255.255.255",
        "224.0.0.1",
    ]
    if r.random() < 0.3:
        return r.choice(specials) + (":" + str(r.randint(0,65535)) if r.random()<0.6 else "")
    return ".".join(str(r.randint(0,255)) for _ in range(4)) + (":" + str(r.randint(0,65535)) if r.random()<0.8 else "")

def _random_ipv6(r: random.Random) -> str:
    # Generate a simple full form or compressed
    if r.random() < 0.5:
        parts = [f"{r.randint(0,0xFFFF):x}" for _ in range(8)]
        s = ":".join(parts)
    else:
        # compressed with ::
        left = [f"{r.randint(0,0xFFFF):x}" for _ in range(r.randint(0,6))]
        right = [f"{r.randint(0,0xFFFF):x}" for _ in range(r.randint(0,6-len(left)))]
        s = ":".join(left) + "::" + ":".join(right)
        if s.startswith("::") and s != "::":
            pass
    if r.random() < 0.6:
        s += f":{r.randint(0,65535)}"
    return s

def _random_addr_string(r: random.Random) -> str:
    return _random_ipv4(r) if r.random() < 0.6 else _random_ipv6(r)

