    ]
    if r.random() < 0.7:
        return r.choice(corpus)[:max_len]
    # Build a small random but valid JSON string array/object
    def rnd_str():
        # Simple JSON-safe string
        s = ''.join(chr(r.randint(32, 126)) for _ in range(r.randint(0, 16)))
        s = s.replace('"', '\\"')
        return f"\"{s}\""
    if r.random() < 0.5:
        arr = ",".join(str(r.randint(-1000, 1000)) if r.random()<0.5 else rnd_str() for _ in range(r.randint(0, 8)))
        j = f"[{arr}]".encode()
    else:
        items = []
        for _ in range(r.randint(0, 6)):
            key = rnd_str()
            val = (str(r.randint(-1000,1000)) if r.random()<0.4 else rnd_str())
            items.append(f"{key}:{val}")
        j = ("{" + ",".join(items) + "}").encode()
    return j[:max_len]

def _choose_profile(r: random.Random):
    # Profiles aligned with fuzzer stubs usage patterns
    # 0: memory ops random binary
    # 1: I/O read buffer size random
    # 2: I/O write payload texty
    # 3: UDP/TCP payload small
    # 4: str_hex data
    # 5: JSON valid buffers
    weights = [3, 1, 1, 1, 1, 3]
    tot = sum(weights)
    x = r.randint(1, tot)
    acc = 0
    for i, w in enumerate(weights):
        acc += w
        if x <= acc:
            return i
    return 0

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    profile = _choose_profile(r)
    # Cap overall size <= 4096
    if profile == 0:
        # memory ops: between 1 and 1024 bytes
        n = r.randint(1, 1024)
        return _rand_bytes(r, n)
    elif profile == 1:
        # io_read target buffer: ensure non-empty small to medium
        n = r.randint(1, 1024)
        return _rand_bytes(r, n)
    elif profile == 2:
        # io_write payload: mixture of text and binary but more texty
        n = r.randint(1, 1024)
        # Bias to include newlines for line-oriented pieces
        base = bytearray()
        while len(base) < n:
            if r.random() < 0.2:
                base.extend(r.choice([b"\n", b"\r\n", b"\t"]))
            elif r.random() < 0.7:
                base.append(r.choice(list(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 _-./:")))
            else:
                base.append(r.getrandbits(8))
        return bytes(base[:n])
    elif profile == 3:
        # Network payload up to 512
        n = r.randint(1, 512)
        return _rand_bytes(r, n)
    elif profile == 4:
        # str_hex input data: max 127 to fit in dst[256]
        n = r.randint(0, 127)
        # Include some structured bytes to observe hex patterns
        data = bytearray()
        # Prepend a small header sometimes
        if r.random() < 0.5 and n >= 4:
            data.extend(struct.pack("<I", r.getrandbits(32)))
        while len(data) < n:
            data.append(r.getrandbits(8))
        return bytes(data[:n])
    else:
        # JSON valid inputs; keep size moderate
        max_len = r.randint(2, 512)
        return _interesting_json(r, max_len)
